// English / Swedish. t('key', { var }) looks up the active language and falls back to English.
// tests/core.test.mjs fails if a key exists in one language but not the other, or if the code
// uses a key that is missing.
import { settings } from './store.js';

export const lang = () => (settings()?.lang === 'sv' ? 'sv' : 'en');
export const locale = () => (lang() === 'sv' ? 'sv-SE' : 'en-GB');
export function L(obj) { return obj ? (obj[lang()] ?? obj.en ?? '') : ''; }
export function t(key, vars) {
  let s = DICT[lang()][key] ?? DICT.en[key];
  if (s === undefined) { if (typeof console !== 'undefined') console.warn('i18n missing:', key); return key; }
  if (vars) s = s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? ''));
  return s;
}

